1	package cli
2	
3	import (
4		"archive/tar"
5		"archive/zip"
6		"compress/gzip"
7		"context"
8		"crypto/sha256"
9		"encoding/hex"
10		"errors"
11		"fmt"
12		"io"
13		"net"
14		"net/http"
15		"net/url"
16		"os"
17		"path"
18		"path/filepath"
19		"runtime"
20		"slices"
21		"strings"
22		"time"
23	)
24	
25	// Release-asset download. The one irreducibly forge-specific piece of the
26	// plugin system is where release binaries live; it's contained here as a
27	// small per-host URL convention table with a declarative escape hatch
28	// (download_url in entire-plugin.yml). Everything else — version listing,
29	// metadata, the index — runs on the git protocol.
30	
31	// errAssetNotFound distinguishes "this tag has no matching asset" (worth
32	// trying the next-highest tag — a pushed tag whose release isn't published
33	// yet) from transport errors (not worth retrying on another tag).
34	var errAssetNotFound = errors.New("no matching release asset")
35	
36	// errUnverifiedAsset means an asset was reachable but nothing authenticated
37	// it — no checksums.txt covering this platform. Distinct from
38	// errAssetNotFound so it never triggers the next-highest-tag walk: falling
39	// back to an older tag wouldn't make the download any more trustworthy.
40	var errUnverifiedAsset = errors.New("release asset cannot be verified")
41	
42	// requireSecureAssetURL gates every plugin HTTP fetch on a transport that a
43	// network attacker can't rewrite.
44	//
45	// Plaintext HTTP is not merely "less good" here: the asset and the
46	// checksums.txt that authenticates it come from the same origin, so an
47	// attacker who can rewrite one can rewrite both, and checksum verification
48	// becomes theatre. HTTPS is therefore required for anything off-machine.
49	//
50	// Loopback is exempt so httptest-backed tests and local forge experiments
51	// keep working — traffic that never leaves the machine has no network
52	// attacker to defend against.
53	func requireSecureAssetURL(rawURL string) error {
54		u, err := url.Parse(rawURL)
55		if err != nil {
56			return fmt.Errorf("parse download URL %q: %w", redactURL(rawURL), err)
57		}
58		switch strings.ToLower(u.Scheme) {
59		case "https":
60			return nil
61		case "http":
62			if isLoopbackHost(u.Hostname()) {
63				return nil
64			}
65			return fmt.Errorf("refusing to download %s over plaintext HTTP: the asset and its %s would share an origin, so a network attacker could replace both and checksum verification would prove nothing; serve the release over HTTPS or declare an https download_url in %s",
66				redactURL(rawURL), checksumsFileName, pluginMetadataFileName)
67		default:
68			return fmt.Errorf("plugin downloads must use https; %q has scheme %q", redactURL(rawURL), u.Scheme)
69		}
70	}
71	
72	// isLoopbackHost reports whether host addresses this machine.
73	func isLoopbackHost(host string) bool {
74		if strings.EqualFold(host, "localhost") {
75			return true
76		}
77		if ip := net.ParseIP(host); ip != nil {
78			return ip.IsLoopback()
79		}
80		return false
81	}
82	
83	// maxAssetRedirects bounds the redirect chain for an asset fetch. Release
84	// hosts routinely redirect to a CDN, so some hops are expected.
85	const maxAssetRedirects = 10
86	
87	// pluginHTTPClient bounds the total time for a single asset download.
88	// Plugins can be tens of MB; 5 minutes is generous even on slow links.
89	//
90	// CheckRedirect re-runs the transport check on every hop. Without it the
91	// https-only rule is trivially bypassed: Go's default policy follows up to 10
92	// redirects *across schemes* and only the initial URL was ever validated, so an
93	// https:// entry point could deliver both the asset and its checksums.txt over
94	// plaintext — exactly the outcome requireSecureAssetURL exists to prevent.
95	var pluginHTTPClient = &http.Client{
96		Timeout: 5 * time.Minute,
97		CheckRedirect: func(req *http.Request, via []*http.Request) error {
98			if len(via) >= maxAssetRedirects {
99				return fmt.Errorf("stopped after %d redirects", maxAssetRedirects)
100			}
101			return requireSecureAssetURL(req.URL.String())
102		},
103	}
104	
105	// maxPluginAssetSize caps a downloaded asset. Real plugin binaries are tens
106	// of MB; the cap exists so a misconfigured URL serving an endless stream
107	// can't fill the disk.
108	const maxPluginAssetSize = 512 << 20 // 512 MiB
109	
110	// maxChecksumsSize caps a checksums.txt fetch. One line per released artifact,
111	// so 1 MiB covers thousands.
112	const maxChecksumsSize = 1 << 20
113	
114	// releaseAssetBaseURL returns the URL prefix release assets live under for
115	// the repo's host. GitHub and the Gitea family share a convention; GitLab
116	// has its own. Unknown hosts default to the GitHub-style convention (most
117	// self-hosted forges mirror it) — authors on hosts that don't can declare
118	// download_url in entire-plugin.yml.
119	func releaseAssetBaseURL(repoURL, tag string) (string, error) {
120		u, err := url.Parse(strings.TrimSuffix(repoURL, ".git"))
121		if err != nil {
122			return "", fmt.Errorf("parse repo URL: %w", err)
123		}
124		if u.Scheme != "https" && u.Scheme != "http" {
125			return "", fmt.Errorf("release downloads need an http(s) repo URL, got %q (declare download_url in %s for non-HTTP remotes)", redactURL(repoURL), pluginMetadataFileName)
126		}
127		base := strings.TrimSuffix(u.String(), "/")
128		host := strings.ToLower(u.Hostname())
129		if host == "gitlab.com" || strings.HasPrefix(host, "gitlab.") {
130			return base + "/-/releases/" + url.PathEscape(tag) + "/downloads/", nil
131		}
132		return base + "/releases/download/" + url.PathEscape(tag) + "/", nil
133	}
134	
135	// expandDownloadTemplate expands the author-declared download_url template.
136	// Placeholders: {name} {tag} {version} {os} {arch} {asset}.
137	func expandDownloadTemplate(tmpl, name, tag, asset string) string {
138		r := strings.NewReplacer(
139			"{name}", name,
140			"{tag}", tag,
141			"{version}", strings.TrimPrefix(tag, "v"),
142			"{os}", runtime.GOOS,
143			"{arch}", runtime.GOARCH,
144			"{asset}", asset,
145		)
146		return r.Replace(tmpl)
147	}
148	
149	// archAliases maps a GOARCH to the spellings seen in release asset names.
150	func archAliases(goarch string) []string {
151		switch goarch {
152		case "amd64":
153			return []string{"amd64", "x86_64"}
154		case "arm64":
155			return []string{"arm64", "aarch64"}
156		default:
157			return []string{goarch}
158		}
159	}
160	
161	// osAliases maps a GOOS to asset-name spellings, most specific first.
162	func osAliases(goos string) []string {
163		if goos == darwinGOOS {
164			return []string{"darwin", "macos"}
165		}
166		return []string{goos}
167	}
168	
169	// platformArchAliases returns the arch spellings to try for goos. On darwin it
170	// appends "all", which is where goreleaser puts the universal-binary marker:
171	// the name is entire-<x>_<ver>_darwin_all, so "all" belongs in the arch slot.
172	// It used to sit in the OS slot, generating _all_arm64 — a spelling no forge
173	// produces — so the darwin_all fallback the docs promise never actually
174	// matched and universal-only releases could not be installed at all.
175	func platformArchAliases(goos, goarch string) []string {
176		aliases := archAliases(goarch)
177		if goos == darwinGOOS {
178			aliases = append(aliases, "all")
179		}
180		return aliases
181	}
182	
183	// assetCandidates returns release asset filenames to try for this platform,
184	// in preference order: archives before raw binaries, version-in-name
185	// (goreleaser's default template) before version-less.
186	func assetCandidates(name, tag string) []string {
187		binName := pluginBinaryPrefix + name
188		version := strings.TrimPrefix(tag, "v")
189		stems := make([]string, 0, 16)
190		for _, osName := range osAliases(runtime.GOOS) {
191			for _, arch := range platformArchAliases(runtime.GOOS, runtime.GOARCH) {
192				stems = append(stems,
193					fmt.Sprintf("%s_%s_%s_%s", binName, version, osName, arch),
194					fmt.Sprintf("%s_%s_%s", binName, osName, arch),
195				)
196			}
197		}
198		exts := []string{".tar.gz", ".zip", ""}
199		if runtime.GOOS == windowsGOOS {
200			exts = []string{".zip", ".tar.gz", windowsExeExt}
201		}
202		var out []string
203		for _, ext := range exts {
204			for _, stem := range stems {
205				out = append(out, stem+ext)
206			}
207		}
208		return out
209	}
210	
211	// checksumsFileName is the conventional name of a release's checksum
212	// manifest (goreleaser's default).
213	const checksumsFileName = "checksums.txt"
214	
215	// checksumCandidates returns filenames the checksum manifest may go by.
216	func checksumCandidates(name, tag string) []string {
217		binName := pluginBinaryPrefix + name
218		version := strings.TrimPrefix(tag, "v")
219		return []string{
220			checksumsFileName,
221			fmt.Sprintf("%s_%s_checksums.txt", binName, version),
222			binName + "_checksums.txt",
223		}
224	}
225	
226	// parseChecksums parses "hex  filename" lines (sha256sum format) into a
227	// filename → digest map.
228	func parseChecksums(data []byte) map[string]string {
229		out := make(map[string]string)
230		for _, line := range strings.Split(string(data), "\n") {
231			fields := strings.Fields(line)
232			if len(fields) != 2 {
233				continue
234			}
235			// sha256sum marks binary-mode files with a leading *.
236			out[strings.TrimPrefix(fields[1], "*")] = strings.ToLower(fields[0])
237		}
238		return out
239	}
240	
241	// selectAssetFromChecksums picks the preferred candidate present in the
242	// checksum manifest. The manifest lists what was actually published, so
243	// this avoids probing candidate URLs one by one.
244	func selectAssetFromChecksums(sums map[string]string, name, tag string) (asset, digest string, ok bool) {
245		for _, c := range assetCandidates(name, tag) {
246			if d, present := sums[c]; present {
247				return c, d, true
248			}
249		}
250		return "", "", false
251	}
252	
253	// fetchedAsset is the result of downloadPluginAsset: a verified asset on
254	// disk in a caller-owned staging dir.
255	type fetchedAsset struct {
256		// Path is the downloaded asset file inside the staging dir.
257		Path string
258		// Asset is the asset filename that matched.
259		Asset string
260		// SHA256 is the hex digest of the downloaded bytes.
261		SHA256 string
262		// Verified is true when SHA256 was checked against a digest published in
263		// the release's checksum manifest, rather than merely computed from
264		// whatever arrived. Recorded in the install manifest so `plugin doctor`
265		// can surface unverified installs.
266		Verified bool
267	}
268	
269	// downloadPluginAsset locates and downloads the release asset for name@tag
270	// into stagingDir, verifying against the release's checksum manifest when
271	// one is published. Returns errAssetNotFound (possibly wrapped) when the
272	// tag has no asset for this platform.
273	func downloadPluginAsset(ctx context.Context, meta *PluginMetadata, repoURL, name, tag, stagingDir string, allowUnverified bool) (*fetchedAsset, error) {
274		// Resolve the prefix once. It does not depend on the asset name, so
275		// deriving it per candidate meant re-parsing the repo URL ~36 times in the
276		// probe loop and carrying an error return through three call sites for a
277		// failure that can only happen here.
278		var assetURL func(asset string) string
279		if meta != nil && meta.DownloadURL != "" {
280			assetURL = func(asset string) string {
281				return expandDownloadTemplate(meta.DownloadURL, name, tag, asset)
282			}
283		} else {
284			base, err := releaseAssetBaseURL(repoURL, tag)
285			if err != nil {
286				return nil, err
287			}
288			assetURL = func(asset string) string { return base + asset }
289		}
290	
291		// A download_url template without {asset} is a single fully-specified
292		// URL; there is nothing to select — and no way to locate a checksum
293		// manifest, since every candidate name would expand to the same URL.
294		if meta != nil && meta.DownloadURL != "" && !strings.Contains(meta.DownloadURL, "{asset}") {
295			if !allowUnverified {
296				return nil, fmt.Errorf("%w: %s declares a fixed download_url with no {asset} placeholder, so no %s can be located; add {asset} to the template or install with --allow-unverified",
297					errUnverifiedAsset, pluginMetadataFileName, checksumsFileName)
298			}
299			u := expandDownloadTemplate(meta.DownloadURL, name, tag, "")
300			return fetchAndVerify(ctx, u, assetNameFromURL(u), "", stagingDir)
301		}
302	
303		// Preferred path: fetch the checksum manifest and pick from what was
304		// actually published.
305		for _, cs := range checksumCandidates(name, tag) {
306			data, err := httpGetSmall(ctx, assetURL(cs))
307			if err != nil {
308				continue
309			}
310			asset, digest, ok := selectAssetFromChecksums(parseChecksums(data), name, tag)
311			if !ok {
312				// This manifest lists nothing for the platform. Keep going: a
313				// stale or hand-written root checksums.txt must not mask a
314				// goreleaser manifest under another candidate name, or a
315				// published asset still reachable by the probe fallback.
316				// Falling through doesn't weaken verification — an attacker
317				// who controls the manifest could list a malicious digest
318				// directly.
319				continue
320			}
321			return fetchAndVerify(ctx, assetURL(asset), asset, digest, stagingDir)
322		}
323	
324		// Fallback: probe candidates directly (a release published without a
325		// checksum manifest). Nothing authenticates these bytes, so by default an
326		// asset found this way is refused rather than installed.
327		//
328		// The probe still runs when verification is required: it distinguishes
329		// "this tag has no release yet" (errAssetNotFound, worth walking down to
330		// the next tag) from "the release exists but publishes no checksums"
331		// (errUnverifiedAsset, which an older tag wouldn't fix). Getting that
332		// wrong would report a missing release for a plugin that simply doesn't
333		// ship checksums.
334		for _, asset := range assetCandidates(name, tag) {
335			fa, err := fetchAndVerify(ctx, assetURL(asset), asset, "", stagingDir)
336			switch {
337			case errors.Is(err, errAssetNotFound):
338				continue
339			case err != nil:
340				return nil, err
341			case allowUnverified:
342				return fa, nil
343			}
344			_ = os.Remove(fa.Path)
345			return nil, fmt.Errorf("%w: %s %s publishes %s but no %s to authenticate it; ask the author to publish checksums, or install with --allow-unverified",
346				errUnverifiedAsset, name, tag, asset, checksumsFileName)
347		}
348		return nil, fmt.Errorf("%w for %s/%s at %s %s", errAssetNotFound, runtime.GOOS, runtime.GOARCH, redactURL(repoURL), tag)
349	}
350	
351	// assetNameFromURL derives the staging filename for a fully-specified
352	// download_url. Only the URL path contributes: path.Base on the whole URL
353	// folds a query string into the name ("entire-run.tar.gz?token=abc"), which
354	// then misses extractPluginBinary's extension sniff and gets written out as
355	// a raw binary — a silently broken install (and an invalid filename on
356	// Windows).
357	func assetNameFromURL(rawURL string) string {
358		if u, err := url.Parse(rawURL); err == nil && u.Path != "" {
359			return path.Base(u.Path)
360		}
361		trimmed := rawURL
362		if i := strings.IndexAny(trimmed, "?#"); i >= 0 {
363			trimmed = trimmed[:i]
364		}
365		return path.Base(trimmed)
366	}
367	
368	// httpGetSmall fetches a small text resource (checksum manifests).
369	func httpGetSmall(ctx context.Context, rawURL string) ([]byte, error) {
370		if err := requireSecureAssetURL(rawURL); err != nil {
371			return nil, err
372		}
373		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
374		if err != nil {
375			return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
376		}
377		resp, err := pluginHTTPClient.Do(req)
378		if err != nil {
379			return nil, fmt.Errorf("GET %s: %w", redactURL(rawURL), err)
380		}
381		defer resp.Body.Close()
382		if resp.StatusCode != http.StatusOK {
383			return nil, fmt.Errorf("GET %s: %s", redactURL(rawURL), resp.Status)
384		}
385		// readWithinLimit, not a bare LimitReader: this fetches checksums.txt, and
386		// silently truncating it would drop the line covering our asset — turning a
387		// verifiable download into an "unverified" one for a reason nobody could see.
388		data, err := readWithinLimit(resp.Body, maxChecksumsSize)
389		if err != nil {
390			return nil, fmt.Errorf("read %s: %w", redactURL(rawURL), err)
391		}
392		return data, nil
393	}
394	
395	// fetchAndVerify downloads rawURL into stagingDir, streaming the SHA-256 as
396	// it writes. A non-empty wantDigest is enforced; an empty one records the
397	// computed digest. 404/410 map to errAssetNotFound. Partial files are
398	// removed on verification failure so a hostile or truncated download never
399	// lingers in staging.
400	// Note on credentials: rawURL may carry userinfo, because releaseAssetBaseURL
401	// derives the asset URL from the repo URL and url.String() re-serializes it.
402	// The request keeps it — that is how the download authenticates to a private
403	// forge — but every message below goes through redactURL, since main.go prints
404	// command errors to stderr and a download failure is an ordinary event
405	// (network hiccup, 5xx, checksum mismatch), not an exceptional one.
406	func fetchAndVerify(ctx context.Context, rawURL, asset, wantDigest, stagingDir string) (*fetchedAsset, error) {
407		// The asset name is normally one of our own candidates, but the
408		// single-URL download_url template path derives it from the URL and a
409		// future caller could pass a name straight from a remote manifest.
410		// Refuse anything that wouldn't stay inside stagingDir. Backslash is
411		// rejected on every platform — it's a separator on Windows, and a
412		// literal backslash in an asset name is never legitimate.
413		if asset == "" || asset == "." || asset == ".." ||
414			strings.ContainsAny(asset, `/\`) || asset != filepath.Base(asset) {
415			return nil, fmt.Errorf("unsafe release asset name %q", asset)
416		}
417		if err := requireSecureAssetURL(rawURL); err != nil {
418			return nil, err
419		}
420		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
421		if err != nil {
422			return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
423		}
424		resp, err := pluginHTTPClient.Do(req)
425		if err != nil {
426			return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
427		}
428		defer resp.Body.Close()
429		switch resp.StatusCode {
430		case http.StatusOK:
431		case http.StatusNotFound, http.StatusGone:
432			return nil, fmt.Errorf("%w: GET %s: %s", errAssetNotFound, redactURL(rawURL), resp.Status)
433		default:
434			return nil, fmt.Errorf("download %s: %s", redactURL(rawURL), resp.Status)
435		}
436	
437		dest := filepath.Join(stagingDir, asset)
438		out, err := os.Create(dest) //nolint:gosec // dest is inside the caller-owned staging dir; asset name came from our candidate list or checksum manifest
439		if err != nil {
440			return nil, fmt.Errorf("create staging file: %w", err)
441		}
442		h := sha256.New()
443		n, err := io.Copy(io.MultiWriter(out, h), io.LimitReader(resp.Body, maxPluginAssetSize+1))
444		closeErr := out.Close()
445		if err != nil {
446			_ = os.Remove(dest)
447			return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
448		}
449		if closeErr != nil {
450			_ = os.Remove(dest)
451			return nil, fmt.Errorf("write staging file: %w", closeErr)
452		}
453		if n > maxPluginAssetSize {
454			_ = os.Remove(dest)
455			return nil, fmt.Errorf("download %s: exceeds %d byte limit", redactURL(rawURL), int64(maxPluginAssetSize))
456		}
457		got := hex.EncodeToString(h.Sum(nil))
458		if wantDigest != "" && !strings.EqualFold(got, wantDigest) {
459			_ = os.Remove(dest)
460			return nil, fmt.Errorf("checksum mismatch for %s: got %s, want %s", asset, got, wantDigest)
461		}
462		return &fetchedAsset{Path: dest, Asset: asset, SHA256: got, Verified: wantDigest != ""}, nil
463	}
464	
465	// extractPluginBinary locates the plugin executable inside the downloaded
466	// asset and writes it to destPath (mode 0755 on Unix). Raw binaries are
467	// copied; .tar.gz/.tgz and .zip archives are searched for an entry whose
468	// basename matches entire-<name>[.exe], wherever it sits in the archive.
469	func extractPluginBinary(assetPath, name, destPath string) error {
470		binName := pluginBinaryPrefix + name
471		lower := strings.ToLower(assetPath)
472		switch {
473		case strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz"):
474			return extractFromTarGz(assetPath, binName, destPath)
475		case strings.HasSuffix(lower, ".zip"):
476			return extractFromZip(assetPath, binName, destPath)
477		default:
478			src, err := os.Open(assetPath) //nolint:gosec // staging-dir file we just wrote
479			if err != nil {
480				return fmt.Errorf("open asset: %w", err)
481			}
482			defer src.Close()
483			return writeExecutable(src, destPath)
484		}
485	}
486	
487	// matchesPluginBinary reports whether an archive entry basename is the
488	// plugin binary, tolerating a Windows extension.
489	func matchesPluginBinary(entryName, binName string) bool {
490		base := path.Base(filepath.ToSlash(entryName))
491		if base == binName {
492			return true
493		}
494		return runtime.GOOS == windowsGOOS && strings.EqualFold(base, binName+windowsExeExt)
495	}
496	
497	// safeArchiveEntry rejects entry names that could escape an extraction
498	// root. We only ever extract a single matched file to a fixed dest, so this
499	// is defense in depth against a hostile archive masking as a plugin.
500	func safeArchiveEntry(entryName string) bool {
501		clean := archiveEntryPath(entryName)
502		return !strings.HasPrefix(clean, "../") && !path.IsAbs(clean) && !strings.Contains(entryName, "\x00")
503	}
504	
505	// preferredArchiveEntry picks among entries whose basename matches the plugin
506	// binary. Shallowest path wins, then lexicographic order.
507	//
508	// Selection has to be deterministic and independent of archive order. Matching
509	// is by basename, so an archive can legitimately hold more than one candidate —
510	// goreleaser writes the binary at the root by default but nests it under a
511	// versioned directory with wrap_in_directory, and archives also ship things like
512	// completions/entire-<name>. Taking whichever came first meant the installed
513	// binary depended on the order the author's tar happened to be built in.
514	//
515	// Shallowest-first encodes the convention: the real binary sits at the root, or
516	// at worst one directory down; a same-named file deeper in the tree is a
517	// completion script or a doc, not the command.
518	func preferredArchiveEntry(names []string, binName string) string {
519		p := archiveEntryPicker{binName: binName}
520		for _, name := range names {
521			p.consider(name)
522		}
523		return p.best
524	}
525	
526	// archiveEntryPicker keeps only the best candidate seen so far, so an archive
527	// can be scanned without materializing every entry name.
528	//
529	// That matters because the entry list is remote-controlled and the only prior
530	// check on it is that the asset's sha256 matched what the release published.
531	// Entry headers compress extremely well, so the 512 MiB maxPluginAssetSize
532	// admits tens of millions of them — enough that collecting the names would
533	// cost gigabytes of heap to end up choosing between the one or two entries a
534	// real release actually contains. A running minimum costs one string.
535	type archiveEntryPicker struct {
536		binName string
537		best    string
538		depth   int
539	}
540	
541	func (p *archiveEntryPicker) consider(name string) {
542		if !safeArchiveEntry(name) || !matchesPluginBinary(name, p.binName) {
543			return
544		}
545		clean := archiveEntryPath(name)
546		depth := strings.Count(clean, "/")
547		if p.best == "" || depth < p.depth || (depth == p.depth && clean < p.best) {
548			p.best, p.depth = clean, depth
549		}
550	}
551	
552	// archiveEntryPath normalizes an archive entry name to cleaned, slash-separated
553	// form. Selection and extraction must normalize identically — otherwise the
554	// entry preferredArchiveEntry picked would not match the one extraction
555	// compares against, and the install would fail on an archive that contains the
556	// binary.
557	func archiveEntryPath(name string) string {
558		return path.Clean(filepath.ToSlash(name))
559	}
560	
561	// errNoArchiveEntry reports an archive that holds no usable binary, either
562	// because nothing matched or because the chosen entry vanished between passes.
563	func errNoArchiveEntry(archivePath, binName string) error {
564		return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
565	}
566	
567	// walkTarGz calls fn for each regular-file entry in a tar.gz, stopping early
568	// when fn returns stop. Both the listing pass and the extraction pass go
569	// through it, so the open/gzip/tar scaffolding exists in one place.
570	func walkTarGz(archivePath string, fn func(hdr *tar.Header, r io.Reader) (stop bool, err error)) error {
571		f, err := os.Open(archivePath) //nolint:gosec // staging-dir file we just wrote
572		if err != nil {
573			return fmt.Errorf("open archive: %w", err)
574		}
575		defer f.Close()
576		gz, err := gzip.NewReader(f)
577		if err != nil {
578			return fmt.Errorf("open gzip: %w", err)
579		}
580		defer gz.Close()
581		tr := tar.NewReader(gz)
582		for {
583			hdr, err := tr.Next()
584			if errors.Is(err, io.EOF) {
585				return nil
586			}
587			if err != nil {
588				return fmt.Errorf("read tar: %w", err)
589			}
590			if hdr.Typeflag != tar.TypeReg {
591				continue
592			}
593			stop, err := fn(hdr, tr)
594			if err != nil {
595				return err
596			}
597			if stop {
598				return nil
599			}
600		}
601	}
602	
603	// selectTarEntry scans a tar.gz and returns the entry extraction should take,
604	// holding one candidate name at a time rather than the whole listing.
605	func selectTarEntry(archivePath, binName string) (string, error) {
606		p := archiveEntryPicker{binName: binName}
607		if err := walkTarGz(archivePath, func(hdr *tar.Header, _ io.Reader) (bool, error) {
608			p.consider(hdr.Name)
609			return false, nil
610		}); err != nil {
611			return "", err
612		}
613		return p.best, nil
614	}
615	
616	func extractFromTarGz(archivePath, binName, destPath string) error {
617		// Two passes: a tar stream cannot seek backwards, so choosing among
618		// candidates means selecting first and extracting second. The cost is one
619		// extra inflation of an archive already capped at maxPluginAssetSize —
620		// ~100ms on a 50 MiB archive, against a download measured in seconds —
621		// which buys a deterministic choice.
622		want, err := selectTarEntry(archivePath, binName)
623		if err != nil {
624			return err
625		}
626		if want == "" {
627			return errNoArchiveEntry(archivePath, binName)
628		}
629		found := false
630		if err := walkTarGz(archivePath, func(hdr *tar.Header, r io.Reader) (bool, error) {
631			if archiveEntryPath(hdr.Name) != want {
632				return false, nil
633			}
634			found = true
635			return true, writeExecutable(r, destPath)
636		}); err != nil {
637			return err
638		}
639		if !found {
640			return errNoArchiveEntry(archivePath, binName)
641		}
642		return nil
643	}
644	
645	func extractFromZip(archivePath, binName, destPath string) error {
646		zr, err := zip.OpenReader(archivePath)
647		if err != nil {
648			return fmt.Errorf("open zip: %w", err)
649		}
650		defer zr.Close()
651		p := archiveEntryPicker{binName: binName}
652		for _, f := range zr.File {
653			if !f.FileInfo().IsDir() {
654				p.consider(f.Name)
655			}
656		}
657		want := p.best
658		if want == "" {
659			return errNoArchiveEntry(archivePath, binName)
660		}
661		// zip is random-access, so the chosen entry is reachable directly — no
662		// second scan, and no Close deferred inside a loop.
663		i := slices.IndexFunc(zr.File, func(f *zip.File) bool {
664			return !f.FileInfo().IsDir() && archiveEntryPath(f.Name) == want
665		})
666		if i < 0 {
667			return errNoArchiveEntry(archivePath, binName)
668		}
669		rc, err := zr.File[i].Open()
670		if err != nil {
671			return fmt.Errorf("open zip entry: %w", err)
672		}
673		defer rc.Close()
674		return writeExecutable(rc, destPath)
675	}
676	
677	// fileSHA256 returns the hex SHA-256 of the file at path. Used to record the
678	// installed binary's digest and to re-check it in `plugin doctor`.
679	func fileSHA256(path string) (string, error) {
680		f, err := os.Open(path) //nolint:gosec // path is inside the managed plugin tree
681		if err != nil {
682			return "", fmt.Errorf("open %s: %w", filepath.Base(path), err)
683		}
684		defer f.Close()
685		h := sha256.New()
686		if _, err := io.Copy(h, f); err != nil {
687			return "", fmt.Errorf("read %s: %w", filepath.Base(path), err)
688		}
689		return hex.EncodeToString(h.Sum(nil)), nil
690	}
691	
692	// writeExecutable writes r to destPath with the executable bit set, bounded by
693	// maxPluginAssetSize. Explicit chmod (not inherited archive mode) because
694	// zip-built and raw-binary releases routinely lose the bit — the #1
695	// "downloaded plugin doesn't run" failure.
696	func writeExecutable(r io.Reader, destPath string) error {
697		return writeExecutableLimited(r, destPath, maxPluginAssetSize)
698	}
699	
700	// writeExecutableLimited is writeExecutable with an explicit cap, so the
701	// oversize path is testable without materializing 512 MiB.
702	//
703	// The cap lives here rather than in each caller's io.LimitReader because a
704	// bare LimitReader makes truncation invisible: io.Copy returns a nil error at
705	// the limit, so an archive entry larger than the cap was silently truncated
706	// and installed as the plugin binary with the install reporting success. Worse
707	// since binary_sha256 landed — the digest is computed from the truncated bytes,
708	// so `plugin doctor` would confirm the corrupt binary as intact. Reading one
709	// byte past the cap makes the overflow detectable, mirroring fetchAndVerify.
710	func writeExecutableLimited(r io.Reader, destPath string, limit int64) error {
711		// Write to a sibling temp file and rename into place. Two reasons, both
712		// load-bearing:
713		//
714		//  - O_CREATE without O_EXCL follows a symlink at destPath, so a symlink
715		//    planted at pkg/<name>/entire-<name> by an earlier malicious plugin
716		//    would redirect this write anywhere the user can write (~/.zshrc, a git
717		//    hook). Creating a fresh temp name and renaming cannot follow anything.
718		//  - Opening destPath with O_TRUNC destroys the working binary before the
719		//    new bytes are known-good, so an interrupted or failed copy left the
720		//    plugin broken. This path is the *normal* one whenever staging and the
721		//    managed dir are on different filesystems (a tmpfs /tmp), not an edge
722		//    case.
723		tmp, err := os.CreateTemp(filepath.Dir(destPath), ".tmp-"+filepath.Base(destPath)+"-*")
724		if err != nil {
725			return fmt.Errorf("create staging binary: %w", err)
726		}
727		tmpName := tmp.Name()
728		defer func() { _ = os.Remove(tmpName) }() // no-op once the rename succeeds
729	
730		n, err := io.Copy(tmp, io.LimitReader(r, limit+1))
731		if err != nil {
732			_ = tmp.Close()
733			return fmt.Errorf("write binary: %w", err)
734		}
735		if err := tmp.Close(); err != nil {
736			return fmt.Errorf("close binary: %w", err)
737		}
738		if n > limit {
739			return fmt.Errorf("plugin binary exceeds the %d byte limit", limit)
740		}
741		// CreateTemp makes 0600; the dispatcher needs it executable.
742		if err := os.Chmod(tmpName, 0o755); err != nil { //nolint:gosec // a plugin binary must be executable
743			return fmt.Errorf("set executable bit: %w", err)
744		}
745		if err := os.Rename(tmpName, destPath); err != nil {
746			return fmt.Errorf("place binary: %w", err)
747		}
748		return nil
749	}
